import{_ as t,o as r,c as a,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const p=JSON.parse('{"title":"IS373 assignment roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"course-roadmap.md","filePath":"course-roadmap.md","lastUpdated":1794376220000}'),s={name:"course-roadmap.md"};function i(o,e,d,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="is373-assignment-roadmap" tabindex="-1">IS373 assignment roadmap <a class="header-anchor" href="#is373-assignment-roadmap" aria-label="Permalink to &quot;IS373 assignment roadmap&quot;">​</a></h1><p><span class="status-label">FA26 IS373-001 · CANVAS CHECKED NOVEMBER 5, 2026</span></p><p>Use this project as an instructor example of a traceable development process: <strong>research → planning and specification → construction → testing and improvement</strong>. The architecture and research library are drafts. The RAG application has not been implemented. Students develop their own evidence, bounded choices, and contributions; this stack is an option to study, not a new course requirement.</p><h2 id="keep-three-deliverables-distinct" tabindex="-1">Keep three deliverables distinct <a class="header-anchor" href="#keep-three-deliverables-distinct" aria-label="Permalink to &quot;Keep three deliverables distinct&quot;">​</a></h2><ol><li><strong>Individual portfolio + career research:</strong> investigate real employer needs and build your own professional presentation for a chosen role and reader.</li><li><strong>Individual RAG app + technical research:</strong> import permitted content and build your own hosted, source-supported retrieval/chat application using vector search, graph search, or both with a reason.</li><li><strong>Group content system + problem research:</strong> build one useful shared content workflow with your team, with attributable individual contributions and cross-review.</li></ol><p>Your portfolio can showcase your RAG app and your contribution to the group system. They remain distinct deliverables. Each individual review collects two separately labeled sections; the group system uses its separate group review.</p><h2 id="research-now-then-plan-and-specify" tabindex="-1">Research now, then plan and specify <a class="header-anchor" href="#research-now-then-plan-and-specify" aria-label="Permalink to &quot;Research now, then plan and specify&quot;">​</a></h2><p>For career research, the Plan assignment asks for three original employer postings, a comparison of two career directions, a target role/reader, responsibility-to-evidence mapping, portfolio pages, and two lightweight layout alternatives.</p><p>For technical research, investigate vector/graph databases, RAG, chunking, embeddings, entities/relationships, and import. Choose permitted sources and a useful question. Compare approaches, define architecture and resource constraints, identify evaluation questions, and write three to five observable stories/checks. Begin at the <a href="/knowledge-lab/research/">research library</a>.</p><p>Our proposed specification artifacts include the <a href="/knowledge-lab/architecture/overview">architecture</a>, <a href="/knowledge-lab/architecture/contracts">contracts</a>, <a href="/knowledge-lab/decisions/">decisions</a>, and <a href="/knowledge-lab/validation">validation plan</a>. Use their structure to make your own scope reviewable. A working hosted application is not required at Plan; identify local setup and planned links honestly.</p><h2 id="course-milestones" tabindex="-1">Course milestones <a class="header-anchor" href="#course-milestones" aria-label="Permalink to &quot;Course milestones&quot;">​</a></h2><p>All times are <strong>Eastern</strong>. Links require the normal Canvas course access. Assignment pages remain authoritative for instructions and any later changes.</p><table tabindex="0"><thead><tr><th>Phase</th><th>Review and date</th><th>Evidence to demonstrate</th></tr></thead><tbody><tr><td>Research → planning/specification</td><td><strong>Review 1 — Plan · November 17, 2026, 1 p.m.</strong> <a href="https://njit.instructure.com/courses/70733/assignments/769188" target="_blank" rel="noreferrer">Individual</a> · <a href="https://njit.instructure.com/courses/70733/assignments/769189" target="_blank" rel="noreferrer">Group</a></td><td>Sources, alternatives, reader/problem, bounded architecture and stories/checks. Portfolio and RAG sections remain distinct. Group work identifies owners and different reviewers.</td></tr><tr><td>Construction</td><td><strong>Review 2 — Build · November 24, 2026, 1 p.m.</strong> <a href="https://njit.instructure.com/courses/70733/assignments/769190" target="_blank" rel="noreferrer">Individual</a> · <a href="https://njit.instructure.com/courses/70733/assignments/769191" target="_blank" rel="noreferrer">Group</a></td><td>Hosted foundations and a small real working journey. For the individual RAG app, show import → representation → retrieval → cited answer, with actual checks and honest limits.</td></tr><tr><td>Testing and release</td><td><strong>Review 3 — Checked Release · December 3, 2026, 1 p.m.</strong> <a href="https://njit.instructure.com/courses/70733/assignments/769192" target="_blank" rel="noreferrer">Individual</a> · <a href="https://njit.instructure.com/courses/70733/assignments/769193" target="_blank" rel="noreferrer">Group</a></td><td>Working hosted links, persistent data, source traces, repeatable setup and checks. Evaluate missing evidence, repeat import, and permissions. Check portfolio navigation, keyboard use, mobile readability, and evidence links.</td></tr><tr><td>Peer feedback, improvement, retest</td><td><strong>Review 4 — Improve · December 10, 2026, 11:59 p.m.</strong> <a href="https://njit.instructure.com/courses/70733/assignments/769194" target="_blank" rel="noreferrer">Individual</a> · <a href="https://njit.instructure.com/courses/70733/assignments/769195" target="_blank" rel="noreferrer">Group</a></td><td>A real peer observation, meaningful change, and retest. Complete accurate case studies and current final links. December 8/10 are protected for repairs, feedback, and rehearsal.</td></tr><tr><td>Demonstration</td><td><strong>Demo Day · December 18, 2026, 8:30–11 a.m.</strong> <a href="https://njit.instructure.com/courses/70733/assignments/769196" target="_blank" rel="noreferrer">Individual final</a> · <a href="https://njit.instructure.com/courses/70733/assignments/769197" target="_blank" rel="noreferrer">Group final</a></td><td>Demonstrate final-ready work using the December 10 record/site/repository/check links. Final assessments show 8:30 a.m. in the gradebook and require no new duplicate upload. Joining details and slots follow in Canvas.</td></tr></tbody></table><p>Checks begin during construction and continue through release; the phase labels identify the main emphasis, not a reason to postpone verification.</p><h2 id="build-evidence-for-your-career-portfolio" tabindex="-1">Build evidence for your career portfolio <a class="header-anchor" href="#build-evidence-for-your-career-portfolio" aria-label="Permalink to &quot;Build evidence for your career portfolio&quot;">​</a></h2><p>Show the target reader and problem, the employer or user evidence behind your decisions, your actual contribution, the working result, and the checks that support your claims. Distinguish implemented, checked, hosted, and planned behavior. Explain assistance received accurately. Your RAG and group case studies should connect responsibilities and skills to concrete artifacts.</p><p>For Demo Day, prepare the short PowerPoint requested in the final assignment: problem and audience; solution and live demo; evidence/results; lessons and next steps. Presentation slots, duration, and delivery details will be confirmed in Canvas.</p><h2 id="submission-continuity" tabindex="-1">Submission continuity <a class="header-anchor" href="#submission-continuity" aria-label="Permalink to &quot;Submission continuity&quot;">​</a></h2><p>Reuse one evolving individual record with the headings <strong>1. Portfolio + career research</strong> and <strong>2. RAG app + technical research</strong>, plus the shared team record for <strong>3. Group system + problem research</strong>. Add <strong>changed / checked / next</strong> under each relevant heading and keep site, repository, source, and check links current. Each member identifies their own group contribution. Avoid duplicate weekly reports.</p><p>The existing November 6 Studio assignments retain their scope and original rubrics. This roadmap does not change deadlines or grading. The project review rubrics assess Complete, Thoughtful, Checked, and Understood at 25 points each; use the linked assignment instructions for the full criteria.</p>',20)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
